SEVERANCE_PAY.eligibility:
const employment = ctx.subject.employment;
const ended = get(employment, 'effective_range.to', null);
const served = calendar_distance_days(get(employment, 'service_started_on', employment.effective_range.from), ctx.entry.incurred_on) + 1;
if (ended != null && ctx.entry.incurred_on > ended) return false;
if (get(employment, 'employee_extension_data.section_119_ground', false)) return false;
if (get(employment, 'employee_extension_data.fixed_term_project', false)) return false;
return served >= ctx.lookup.minimum_service_days;

SEVERANCE_PAY.conversion:
const employment = ctx.subject.employment;
const months = calendar_completed_months(get(employment, 'service_started_on', employment.effective_range.from), ctx.entry.incurred_on);
const days = months < 12 ? ctx.lookup.first_tier_days : bracket(months, ctx.lookup.schedule);
return ctx.day_rate * days;

PAY_IN_LIEU_OF_NOTICE.eligibility:
const ended = get(ctx.subject.employment, 'effective_range.to', null);
if (ended != null && ctx.entry.incurred_on > ended) return false;
if (!(ctx.entry.quantity > 0)) return false;
if (ctx.entry.unit === 'MONEY') return true;
return ctx.entry.unit === 'DAY';

MINIMUM_WAGE_ARREARS.eligibility:
const employment = ctx.subject.employment;
const employer = ctx.subject.employer;
const ended = get(employment, 'effective_range.to', null);
if (ended != null && ctx.entry.incurred_on > ended) return false;
if (get(employer, 'entity_extension_data.minimum_wage_exempt', false)) return false;
if (ctx.entry.unit !== 'DAY') return false;
if (!(ctx.entry.quantity > 0)) return false;
const facts = get(employer, 'entity_extension_data', {});
if (get(facts, 'minimum_wage_400_business', false)) return true;
const worksite = get(employment, 'terms.work_region', null);
const region =
	typeof worksite === 'string' && worksite !== ''
		? worksite
		: String(get(facts, 'region', ''));
return Object.hasOwn(ctx.lookup.by_region, region);

MINIMUM_WAGE_ARREARS.conversion:
const employment = ctx.subject.employment;
const facts = get(ctx.subject.employer, 'entity_extension_data', {});
const worksite = get(employment, 'terms.work_region', null);
const region =
	typeof worksite === 'string' && worksite !== ''
		? worksite
		: String(get(facts, 'region', ''));
const minimum = get(facts, 'minimum_wage_400_business', false)
	? ctx.lookup.business_400
	: get(ctx.lookup.by_region, region, 0);
return Math.max(0, minimum - ctx.day_rate) * ctx.entry.quantity;

