const part = calendar_distance_days(add_years(start, whole), ctx.entry.incurred_on) + 1;
const years = whole + (part > ctx.lookup.part_year_days ? 1 : 0);
const days = Math.min(ctx.lookup.maximum_days, ctx.lookup.days_per_year * years);
return ctx.day_rate * days;

