HOLIDAY_NOT_GRANTED.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const rate = get(terms, 'rate', {});
// s.64 pays at the s.62 rate: a monthly wage already pays the holiday (s.56(1)), so 1×; a day or hour
// rate has no weekly-holiday pay, so 2× (s.62(2)). An entry does not say which holiday, so a daily
// worker's traditional or annual holiday (s.62(1), 1×) is paid above the minimum.
const multiple = rate.unit === 'MONTHLY' ? ctx.lookup.paid_multiple : ctx.lookup.unpaid_multiple;
return ctx.hour_rate * multiple * ctx.entry.quantity;

SECURITY_DEPOSIT.eligibility:
const employment = ctx.subject.employment;
const ended = get(employment, 'effective_range.to', null);
if (ended != null && ctx.entry.incurred_on > ended) return false;
const post = get(employment, 'employee_extension_data.security_deposit_post', false);
if (!post) return post;
if (ctx.entry.unit !== 'MONEY') return false;
return ctx.entry.quantity > 0;

STATUTORY_REFUND.eligibility:
