if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
return true;

OVERTIME.conversion:
const overtime_category = get(ctx.subject.employment, 'employee_extension_data.overtime_category', '');
const multiple =
	overtime_category === 'SECTION_65_OTHER' ? 1 : ctx.lookup.multiplier;
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
// LPA s.61: hours past the normal day, every hour of a day off.
const plain = get(ctx, 'work.days', []).filter((day) => !holiday(day) && ['WORK', 'OFF'].includes(day.day_type));
const quantity = sum(plain.map((day) => Number(get(day, day.day_type === 'OFF' ? 'worked_hours' : 'overtime_hours', 0))));
return ctx.hour_rate * multiple * quantity;

HOLIDAY_WORK.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const day_hours = Number(terms.normal_hours_per_day);
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const off = (day) => day.day_type === 'REST' || holiday(day);
// LPA s.62: normal hours on a holiday or rest day. A monthly wage already pays the day, so it adds one times; a daily or hourly wage does not, so two.
const multiple = get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY' ? ctx.lookup.paid_multiple : ctx.lookup.unpaid_multiple;
// The employer's rest-day hourly multiple stands on each weekly-holiday hour where it pays more than s.62.
const rest = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const times = (day) => (day.day_type === 'REST' && !holiday(day) ? Math.max(multiple, rest) : multiple);
const paid = sum(get(ctx, 'work.days', []).filter(off).map((day) => Math.min(Number(get(day, 'worked_hours', 0)), day_hours) * times(day)));
return ctx.hour_rate * paid;

HOLIDAY_OVERTIME.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
const overtime_category = get(ctx.subject.employment, 'employee_extension_data.overtime_category', '');
const day_hours = Number(terms.normal_hours_per_day);
const multiple =
	overtime_category === 'SECTION_65_OTHER' ? 1 : ctx.lookup.multiplier;
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const off = (day) => day.day_type === 'REST' || holiday(day);
// LPA s.63: hours past the normal day on a holiday or rest day.
// The employer's rest-day hourly multiple stands on each weekly-holiday hour where it pays more than s.63.
const rest = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const times = (day) => (day.day_type === 'REST' && !holiday(day) ? Math.max(multiple, rest) : multiple);
const paid = sum(get(ctx, 'work.days', []).filter(off).map((day) => Math.max(0, Number(get(day, 'worked_hours', 0)) - day_hours) * times(day)));
return ctx.hour_rate * paid;

FIXED_ALLOWANCE.conversion:
const coverage = ctx.run.salary_coverage;
const amount = Number(get(ctx.subject.employment, 'terms.allowances.FIXED_ALLOWANCE.amount', 0));
const days = calendar_distance_days(coverage.from, coverage.to) + 1;
const month_days = calendar_distance_days(month_start(coverage.from), month_end(coverage.from)) + 1;
return ((amount * days) / month_days) * ctx.paid_share;

SSO.eligibility:
const data = get(ctx.subject.employment, 'employee_extension_data', {});
if (get(data, 'sso_excluded_category', null) !== null) return false;
// Wages here are pay for normal hours (SSA s.5, WCA s.5): overtime and holiday-work pay sit in ADDITIONAL_WAGES.
const base = get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay);
if (base === 0) return false;
const dob = get(ctx.subject.employment, 'payroll.date_of_birth', null);
if (dob === null) return true;
const age = age_on(dob, ctx.run.salary_coverage.from);
if (age < ctx.lookup.minimum_age) return false;
if (age <= ctx.lookup.maximum_age) return true;
return get(data, 'sso_continuing_insured', false) === true;

SSO.employee_amount:
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const from = ctx.run.salary_coverage.from;
// SSA s.46: the contribution is on the month's wages, so one month's runs are one month: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
// Wages here are pay for normal hours (SSA s.5, WCA s.5): overtime and holiday-work pay sit in ADDITIONAL_WAGES.
const wages = get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay) + before('ORDINARY_WAGES');
const owed = () => {
if (wages <= 0) return 0;
const base = clamp(wages, ctx.lookup.minimum_wage_base, ctx.lookup.maximum_wage_base);
const ordinary = round(base * ctx.lookup.rate, ctx.lookup.rounding_unit, 'HALF_UP');
if (!ctx.lookup.relief_regions.includes(get(entity, 'region', ''))) return ordinary;
if (from < ctx.lookup.relief_from) return ordinary;
if (from > ctx.lookup.relief_to) return ordinary;
// Ministry of Labour notification B.E. 2569: employers registered in the nine southern provinces
// pay 3 percent a side for December 2025 to May 2026, without any application.
const relief = round((base * ctx.lookup.relief_percent) / 100, ctx.lookup.rounding_unit, 'HALF_UP');
// An SSO assessment of 5 percent for this month means the employer is registered elsewhere.
if (Number(get(entity, 'sso_reviewed_rate_percent', 0)) !== ctx.lookup.rate * 100) return relief;
if (get(entity, 'sso_rate_review_month', null) !== from.slice(0, 7)) return relief;
if (get(entity, 'sso_rate_review_reference', '') === '') return relief;
return ordinary;
};
return owed() - before('SSO.employee');

