WCF.eligibility:
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const data = get(ctx.subject.employment, 'employee_extension_data', {});
const wcf = get(get(data, 'statutory', {}), 'WCF', {});
const code = String(get(entity, 'risk_class', ''));
const notified = get(entity, 'wcf_rate_percent', null);
const found = ctx.lookup.rates.find((row) => row.code === code);
if (notified === null && found === undefined)
  throw 'Thailand WCF needs the employer business code (risk_class) or the notified wcf_rate_percent.';
// Wages here are pay for normal hours (SSA s.5, WCA s.5): overtime and holiday-work pay sit in ADDITIONAL_WAGES.
const base = get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay);
if (base <= 0) return false;
const from = ctx.run.salary_coverage.from;
const year = from.slice(0, 4);
const start = get(ctx.subject.employment, 'employment_started_on', get(ctx.subject.employment, 'effective_range.from', ''));
const end = get(ctx.subject.employment, 'effective_range.to', null);
const full_year = start <= year + '-01-01' && (end === null || end >= year + '-12-31');
const part_year = 'Thailand WCF covering less than a full calendar year needs the reviewed proportional annual wage ceiling, matching calendar year and evidence.';
if (!full_year && get(wcf, 'wcf_reviewed_annual_wage_ceiling', null) === null) throw part_year;
if (!full_year && get(wcf, 'wcf_ceiling_review_tax_year', '') !== year) throw part_year;
if (!full_year && get(wcf, 'wcf_ceiling_review_reference', '') === '') throw part_year;
return true;

WCF.employer_amount:
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const data = get(ctx.subject.employment, 'employee_extension_data', {});
const wcf = get(get(data, 'statutory', {}), 'WCF', {});
const code = String(get(entity, 'risk_class', ''));
const notified = get(entity, 'wcf_rate_percent', null);
const found = ctx.lookup.rates.find((row) => row.code === code);
const percent = notified === null ? found.percent : Number(notified);
// WCA s.44: the contribution is on the wages paid, so one month's runs are one month: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const from = ctx.run.salary_coverage.from;
const start = get(ctx.subject.employment, 'employment_started_on', get(ctx.subject.employment, 'effective_range.from', ''));
const end = get(ctx.subject.employment, 'effective_range.to', null);
const full_year = start <= from.slice(0, 4) + '-01-01' &&
  (end === null || end >= from.slice(0, 4) + '-12-31');
const ceiling = full_year
  ? ctx.lookup.annual_wage_ceiling
  : Number(get(wcf, 'wcf_reviewed_annual_wage_ceiling', 0));
// The ceiling is a calendar year's (notification cl.11): the balance holds this year's contributions only.
const paid = get(ctx.balances, 'statutory_contribution', {});
const prior = Object.hasOwn(paid, 'WCF.employer') ? paid['WCF.employer'] : 0;
const cap = round((ceiling * percent) / 100, ctx.lookup.rounding_step, 'HALF_UP');
// Wages here are pay for normal hours (SSA s.5, WCA s.5): overtime and holiday-work pay sit in ADDITIONAL_WAGES.
const wages = get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay) + before('ORDINARY_WAGES');
const charged = round((wages * percent) / 100, ctx.lookup.rounding_step, 'HALF_UP');
return Math.max(0, Math.min(Number(cap) - prior + before('WCF.employer'), Number(charged)) - before('WCF.employer'));

PVD.eligibility:
const data = get(ctx.subject.employment, 'employee_extension_data', {});
const pvd = get(get(data, 'statutory', {}), 'PVD', {});
if (get(pvd, 'kind', '') !== 'MEMBER') return false;
// PVD Act s.3: wages exclude overtime and holiday pay.
const base = get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay);
if (base === 0) return false;
const employee = Number(get(pvd, 'employee_percent', 0));
const employer = Number(get(ctx.subject.employer, 'entity_extension_data.pvd_employer_percent', 0));
const refused = 'Thailand PVD members require registered employee and employer rates of 2%-15%.';
if (employee < ctx.lookup.pvd_minimum_percent) throw refused;
if (employee > ctx.lookup.pvd_maximum_percent) throw refused;
if (employer < ctx.lookup.pvd_minimum_percent) throw refused;
if (employer > ctx.lookup.pvd_maximum_percent) throw refused;
return true;

