PND1.eligibility:
// SEVERANCE is the last cumulative checkpoint: any pay in this run, severance included.
// SEVERANCE is the last cumulative checkpoint: any pay in this run, severance included.
return get(ctx.subtotals, 'SEVERANCE', 0) !== 0;

PND1.employee_amount:
const employment = ctx.subject.employment;
const from = ctx.run.salary_coverage.from;
// The tax year is cash: the year of the pay date, when the balances reset.
const pay_date = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const tax_year = pay_date.slice(0, 4);
const off_cycle = get(ctx.run, 'kind', '') === 'OFF_CYCLE';
const wages = get(ctx.subtotals, 'ORDINARY_WAGES', 0);
// Overtime, a bonus and all of an off-cycle run are extra payments of their month, never projected over the year (Por.96/2543 cl.1(5)).
const ordinary = off_cycle ? 0 : wages;
// Pay in lieu of notice joins them: s.40(1) income, not a s.48(5) lump sum (ruling Kor Kor 0702/760).
const notice_total = get(ctx.subtotals, 'NOTICE_PAY', wages);
const extra = notice_total - ordinary;
// Severance is exempt to 400 days' wages and 600,000 baht, never on retirement, the end of a contract or a
// resignation (MR 126 cl.2(51), MR 394). The taxed part joins the year unless PND1_SEVERANCE takes it apart.
const ground = get(employment, 'employee_extension_data.exit_ground', '');
const exempt = ctx.lookup.severance_taxed_grounds.includes(ground)
  ? 0
  : Math.min(ctx.lookup.severance_daily_wages_limit * ctx.day_rate, ctx.lookup.severance_exemption_limit);
const separate = get(ctx.statutory, 'PND1_SEVERANCE', null) !== null;
const taxed = (severance) => (separate ? 0 : Math.max(0, severance - exempt));
// Actual income and tax this employer already paid in the tax year; reimbursed travel is exempt (s.42(1)).
const ytd = get(ctx.balances, 'ytd', {});
const paid_income = get(ytd, 'NOTICE_PAY', get(ytd, 'GROSS', 0));
const paid_severance = get(ytd, 'SEVERANCE', paid_income) - paid_income;
const paid_taxed = taxed(paid_severance);
const severance = get(ctx.subtotals, 'SEVERANCE', notice_total) - notice_total;
const severance_taxed = taxed(paid_severance + severance) - paid_taxed;
if (ordinary + extra + severance_taxed === 0) return 0;
const paid = get(ctx.balances, 'statutory_contribution', {});
const paid_scheme = (key) => (Object.hasOwn(paid, key) ? paid[key] : 0);
const month = Number(pay_date.slice(5, 7));
// The payments actually due (Por.96/2543 cl.1(1)): none past December or the last month of the contract.
const end = get(employment, 'effective_range.to', null);
const months_left = end === null ? 12 : calendar_completed_months(month_start(from), end) + 1;
const remaining = Math.max(1, Math.min(13 - month, months_left));
// An off-cycle run pays extras only: the year still projects on the contract's month, and this month's salary counts
// once, in the year to date once the on-cycle run has paid it. Someone leaving earns no more months.
const held_month = get(ctx.balances, 'month', {});
const salary_key = pay_date.slice(0, 7) + '.BASIC';
const salary_paid = Object.hasOwn(held_month, salary_key) && Number(held_month[salary_key]) > 0;
const to_come = off_cycle && salary_paid ? remaining - 1 : remaining;
const projected =
  !off_cycle ? ordinary
  : end !== null && end <= ctx.as_of ? 0
  : ctx.month_wage;
const data = get(employment, 'employee_extension_data', {});
const pnd1 = get(get(data, 'statutory', {}), 'PND1', {});
// Earlier-employer income and tax join this PND1 only when the same withholding
// agent/declaration continues; otherwise they are reconciled in the annual return.
const same_agent = get(pnd1, 'same_withholding_agent', false) === true;
const previous_income = same_agent ? Number(get(pnd1, 'previous_employer_income', 0)) : 0;
const previous_tax = same_agent ? Number(get(pnd1, 'previous_employer_tax', 0)) : 0;
// Benefits in kind are taxable but not paid, so no payslip carries them: the year counts
// them over the months of this employment inside it.
const start = String(get(employment, 'employment_started_on', get(employment, 'effective_range.from', '')));
const first_month = start.slice(0, 4) === tax_year ? Number(start.slice(5, 7)) : 1;
const last_month =
  end === null || end.slice(0, 4) > tax_year
    ? 12
    : end.slice(0, 4) < tax_year
      ? 0
      : Number(end.slice(5, 7));
const bik =
  Number(get(employment, 'terms.allowances.BENEFIT_IN_KIND.amount', 0)) *
  Math.max(0, last_month - first_month + 1);
// Actual year-to-date income and the current ordinary pay projected over the payments left.
const regular = paid_income + paid_taxed + previous_income + projected * to_come + bik;
// Revenue Code s.47(3): a non-resident deducts only a spouse and children in Thailand. No input
// records that, so payroll gives neither and the annual return claims them.
const resident = get(employment, 'terms.residency_status', 'RESIDENT') !== 'NON_RESIDENT';
const marital = get(employment, 'payroll.marital_status', 'SINGLE');
const spouse =
  resident && marital === 'MARRIED' && get(employment, 'family', []).some((member) => member.relation === 'SPOUSE' && get(member, 'has_income', null) === false)
    ? ctx.lookup.personal_allowance
    : 0;
const children = resident
  ? (Number(get(pnd1, 'child_allowance_count', 0)) +
      Number(get(pnd1, 'second_child_from_2018_count', 0))) *
    ctx.lookup.child_allowance
  : 0;
const parents =
  Math.min(Number(get(pnd1, 'parents_count', 0)), 4) * ctx.lookup.parent_allowance;
const disabled =
  Number(get(pnd1, 'disabled_dependants_count', 0)) *
  ctx.lookup.disabled_dependant_allowance;
const health = Math.min(
  Number(get(pnd1, 'parents_health_insurance', 0)),
  ctx.lookup.parent_health_insurance_limit
);
const life = Math.min(Number(get(pnd1, 'life_insurance', 0)), ctx.lookup.life_insurance_limit);
const home = Math.min(
  Number(get(pnd1, 'home_loan_interest', 0)),
  ctx.lookup.home_loan_interest_limit
);
const other = Number(get(pnd1, 'other_annual_deductions', 0));
const dob = get(employment, 'payroll.date_of_birth', null);
const age = dob === null ? 0 : age_on(dob, tax_year + '-12-31');
const elderly =
  age >= 65 || get(data, 'disabled', false) === true
    ? Math.max(
        0,
        ctx.lookup.elderly_or_disabled_exemption -
          Number(get(pnd1, 'exempt_190k_used_elsewhere', 0))
      )
    : 0;
// Each scheme is relieved by its own rule: social security as paid (s.47(1)), the provident fund
// inside the combined retirement limit. Employee Welfare Fund savings have no relief.
const months_paid = Math.max(
  1,
  Object.keys(held_month).filter((key) => key.startsWith(tax_year) && key.endsWith('.BASIC')).length
);
const scheme_month = (code) =>
  off_cycle
    ? paid_scheme(code + '.employee') / months_paid
    : Number(get(get(ctx.statutory, code, {}), 'employee', 0));
const scheme_now = (code) => (off_cycle ? Number(get(get(ctx.statutory, code, {}), 'employee', 0)) : 0);
const sso = paid_scheme('SSO.employee') + scheme_now('SSO') + scheme_month('SSO') * to_come;
const pvd = paid_scheme('PVD.employee') + scheme_now('PVD') + scheme_month('PVD') * to_come;
const paid_pension = Number(get(pnd1, 'pension_insurance', 0));
const allowance =
  ctx.lookup.personal_allowance +
  spouse +
  children +
  parents +
  disabled +
  health +
  life +
  home +
  other;
const annual_tax = (gross) => {
  const expense = Math.min(
    gross * ctx.lookup.employment_expense_share,
    ctx.lookup.employment_expense_limit
  );
  const pension = Math.min(
    paid_pension,
    gross * ctx.lookup.pension_insurance_income_share_limit,
    ctx.lookup.pension_insurance_limit
  );
  const retirement = Math.min(pvd + pension, ctx.lookup.combined_retirement_savings_limit);
  const taxable = Math.max(0, gross - expense - allowance - elderly - sso - retirement);
  return ladder(taxable, ctx.lookup.ladder);
};
const regular_tax = annual_tax(regular);
const credited = paid_scheme('PND1.employee') + previous_tax;
// Por.96/2543 cl.1(5): the tax an extra payment adds is withheld whole in the month it is paid.
const extra_tax = annual_tax(regular + extra + severance_taxed) - regular_tax;
return round((off_cycle ? 0 : (regular_tax - credited) / remaining) + extra_tax, ctx.lookup.rounding_step, 'HALF_UP');

PND1_SEVERANCE.eligibility:
// Revenue Code s.48(5): the employee's choice, open from five years of service (Notification No. 45 cl.2(a)).
const employment = ctx.subject.employment;
const data = get(employment, 'employee_extension_data', {});
const pnd1 = get(get(data, 'statutory', {}), 'PND1', {});
if (get(pnd1, 'severance_separate', false) !== true) return false;
const end = add_days(get(employment, 'effective_range.to', ctx.as_of), 1);
return calendar_completed_months(get(employment, 'service_started_on', employment.effective_range.from), end) >= ctx.lookup.qualifying_years * 12;

PND1_SEVERANCE.employee_amount:
const employment = ctx.subject.employment;
const ytd = get(ctx.balances, 'ytd', {});
const notice_total = get(ctx.subtotals, 'NOTICE_PAY', 0);
const paid_income = get(ytd, 'NOTICE_PAY', 0);
const total =
  get(ytd, 'SEVERANCE', paid_income) - paid_income + get(ctx.subtotals, 'SEVERANCE', notice_total) - notice_total;
// Exempt as in PND1. Severance on these grounds has no exemption and counts under cl.1(d) of Notification No. 45.
const ground = get(employment, 'employee_extension_data.exit_ground', '');
const unexempt = ctx.lookup.severance_taxed_grounds.includes(ground);
const exempt = unexempt
  ? 0
  : Math.min(ctx.lookup.severance_daily_wages_limit * ctx.day_rate, ctx.lookup.severance_exemption_limit);
const income = Math.max(0, total - exempt);
const paid = get(ctx.balances, 'statutory_contribution', {});
const withheld = Object.hasOwn(paid, 'PND1_SEVERANCE.employee') ? paid['PND1_SEVERANCE.employee'] : 0;
if (income <= 0) return -withheld;
const start = get(employment, 'service_started_on', employment.effective_range.from);
const end = add_days(get(employment, 'effective_range.to', ctx.as_of), 1);
const whole = Math.trunc(calendar_completed_months(start, end) / 12);
// s.48(5) para 4: 183 days of a part year count as a year; fewer are dropped.
const years = whole + (calendar_distance_days(add_years(start, whole), end) >= ctx.lookup.part_year_days ? 1 : 0);
// Notification No. 45 cl.3(2): cl.1(d) income earns expenses only up to the last month's pay × years.
const base = unexempt ? Math.min(income, ctx.month_wage * years) : income;
const service = Math.min(ctx.lookup.expense_per_year * years, base);
const expense = service + (base - service) * ctx.lookup.expense_share;
// No 150,000 baht exemption here (Royal Decree No. 470), so the 0 percent band of the ladder drops out.
const tax = ladder(income - expense, ctx.lookup.ladder.slice(1));
return round(tax - withheld, ctx.lookup.rounding_step, 'HALF_UP');

