NORMAL_HOURS.validate:
// Labour Protection Act B.E. 2541 s. 23: normal time is at most eight hours a day
// and forty-eight hours a week, or seven and forty-two for hazardous work.
const worked = get(ctx.entry, 'actual_worked_intervals', []);
if (worked.some((row) => get(row, 'end', null) == null)) return true;
const actual = interval_minutes(worked);
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []));
if (actual - overtime > ctx.lookup.minutes_per_day) return false;
const hazardous = get(ctx.subject.employment, 'terms.statutory_work_category', null) === 'HAZARDOUS';
const weekly = hazardous ? ctx.lookup.weekly_minutes_hazardous : ctx.lookup.weekly_minutes;
const from = add_days(ctx.entry.work_date, -6);
const siblings = get(ctx, 'reads.roster_entry', []).filter(
	(day) => day.id !== ctx.entry.id && day.work_date >= from && day.work_date <= ctx.entry.work_date
);
const days = [...siblings, ctx.entry];
if (days.some((day) => get(day, 'actual_worked_intervals', []).some((row) => get(row, 'end', null) == null))) return true;
const normal_minutes = sum(
	days.map(
		(day) =>
			Math.max(
				0,
				interval_minutes(get(day, 'actual_worked_intervals', [])) -
					interval_minutes(get(day, 'planned_overtime_intervals', []))
			)
	)
);
return normal_minutes <= weekly;

REST_BREAK.validate:
// Labour Protection Act B.E. 2541 s. 27: more than five continuous hours need a rest break.
// A split day is the run's aggregate; one recorded span is checked here.
const worked = get(ctx.entry, 'actual_worked_intervals', []);
if (worked.length !== 1) return true;
const row = first(worked);
const end = get(row, 'end', null);
if (end == null) return true;
if (elapsed_minutes(get(row, 'start', null), end) <= ctx.lookup.elapsed_minutes) return true;
return interval_minutes(get(row, 'breaks', [])) >= ctx.lookup.break_minutes;

CHILD_EMPLOYMENT.validate:
// Labour Protection Act B.E. 2541 s. 44: an employer may not employ a child under fifteen.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
return age_on(born, from) >= ctx.lookup.minimum_age;

MINIMUM_WAGE_FLOOR.condition:
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null) return false;
const engagement = String(get(ctx.entry, 'engagement', 'EMPLOYEE'));
return !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);

MINIMUM_WAGE_FLOOR.validate:
const employer = get(ctx.subject.employer, 'entity_extension_data', {});
if (get(employer, 'minimum_wage_exempt', false) === true) return true;
const worksite = get(ctx.entry, 'terms.work_region', null);
const region =
	typeof worksite === 'string' && worksite !== ''
		? worksite
		: String(get(employer, 'region', ''));
const floor = get(employer, 'minimum_wage_400_business', false) === true
	? ctx.lookup.business_400
	: get(ctx.lookup.by_region, region, null);
if (floor === null) return true;
const rate = get(ctx.entry, 'terms.rate', {});
const unit = get(rate, 'unit', null);
const amount = Number(get(rate, 'amount', 0));
const hours = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
// LPA s.68: a month is thirty normal days.
const days = 30;
const daily =
	unit === 'DAILY'
		? amount
		: unit === 'MONTHLY'
			? amount / days
			: amount * hours;
return daily >= floor;

SKILL_STANDARD_WAGE.condition:
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null) return false;
return get(ctx.entry, 'employee_extension_data.skill_standard_day_rate', null) != null;

SKILL_STANDARD_WAGE.validate:
// Labour Protection Act B.E. 2541 s. 90: a certified worker's day wage must reach the
// skill-standard rate of the trade. The rate is a recorded term fact, not a table here.
const rate = get(ctx.entry, 'terms.rate', null);
const amount = get(rate, 'amount', 0);
const unit = get(rate, 'unit', null);
const hours = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
const days = 30;
const daily =
	unit === 'DAILY'
		? amount
		: unit === 'MONTHLY'
			? amount / days
			: amount * hours;
return daily >= get(ctx.entry, 'employee_extension_data.skill_standard_day_rate', 0);

ROSTER_REST_BREAK.validate:
// Labour Protection Act B.E. 2541 s. 27: planned overtime beyond five continuous hours
// needs a recorded rest break. The rest of the day is checked on actual work.
const planned = get(ctx.entry, 'planned_overtime_intervals', []);
if (planned.length !== 1) return true;
const row = first(planned);
const end = get(row, 'end', null);
if (end == null) return true;
if (elapsed_minutes(get(row, 'start', null), end) <= ctx.lookup.elapsed_minutes) return true;
return interval_minutes(get(row, 'breaks', [])) >= ctx.lookup.break_minutes;

CONTRACT_CATEGORIES.validate:
// The contract's engagement is the model's declared enum; this rule checks the
// jurisdiction's work classification and tax-residency categories.
const categories = ctx.lookup.categories;
const work = get(ctx.entry, 'terms.statutory_work_category', null);
if (work != null && !categories.statutory_work_category.includes(work)) return false;
const residency = get(ctx.entry, 'terms.residency_status', null);
if (residency != null && !categories.residency_status.includes(residency)) return false;
return true;

SHARED_STRUCTURED_EMPLOYEE_INPUTS.validate:
// The recorded PVD election and overtime category must meet this version's contract terms.
const data = get(ctx.entry, 'employee_extension_data', {});
const pvd = get(get(data, 'statutory', {}), 'PVD', {});
const percent = get(pvd, 'employee_percent', null);
const member = get(pvd, 'kind', '') === 'MEMBER';
if (member && typeof percent !== 'number') return false;
if (member && percent < ctx.lookup.pvd_minimum_percent) return false;
if (member && percent > ctx.lookup.pvd_maximum_percent) return false;
const overtime = get(data, 'overtime_category', null);
return overtime === null || ctx.lookup.overtime_categories.includes(overtime);

SHARED_STRUCTURED_ENTITY_INPUTS.validate:
// The employer's province and WCF business code are the keys the payroll formulas read.
const entity = get(ctx.entry, 'entity_extension_data', {});
const region = get(entity, 'region', null);
const risk = get(entity, 'risk_class', null);
if (region !== null && typeof region !== 'string') return false;
if (region === '') return false;
if (risk === null) return true;
if (typeof risk !== 'string') return false;
if (risk.length !== ctx.lookup.risk_class_digits) return false;
const digits = '0123456789';
return risk.split('').every((c) => digits.includes(c));

BUSINESS_CASE_EFFECTIVE_INTERVAL.validate:
// A deduction consent's ordered interval begins on or after its receipt and ends after it starts.
const inputs = get(ctx.entry, 'inputs', {});
const opened = get(ctx.entry, 'opened_on', null);
const from = get(inputs, 'effective_from', null);
const to = get(inputs, 'effective_to', null);
if (opened == null || from == null || to == null) return false;
return from >= opened && to >= from;

BUSINESS_CASE_SIGNED_CONSENT.validate:
// A signed consent needs its actual prior signature date and the signed source document.
const inputs = get(ctx.entry, 'inputs', {});
const opened = get(ctx.entry, 'opened_on', null);
const signed = get(inputs, 'signed_on', null);
if (opened == null || signed == null) return false;
return signed <= opened && get(ctx.entry, 'evidence_file', null) != null;

DEDUCTION_CONSENT_DISTINCT_SCOPE.validate:
// Each authorised deduction code occurs once with its actual amount and currency limit.
const inputs = get(ctx.entry, 'inputs', {});
const deductions = get(inputs, 'deductions', null);
if (!Array.isArray(deductions) || deductions.length === 0) return false;
return !deductions.some(
	(row, index) =>
		deductions.some(
			(other, earlier) => earlier < index && get(other, 'code', null) === get(row, 'code', null)
		)
);

ANNUAL_LEAVE.payout:
// LPA s.67 para 1: an employer who ends the employment without a s.119 ground pays the annual holidays of the year of
// termination in proportion to the s.30 entitlement. s.67 para 2: on any termination, the untaken days accumulated under
// s.30 para 3 are paid.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
const end = get(employment, 'effective_range.to', ctx.as_of);
const started = get(employment, 'service_started_on', employment.effective_range.from);
const year = Math.floor(calendar_completed_months(started, end) / 12);
const grant = year * 12 >= ctx.lookup.service_months ? ctx.lookup.grant_days : 0;
const current = Math.min(ctx.entry.quantity, grant);
const dismissed =
  ['DISMISSAL', 'DISMISSAL_FOR_CAUSE', 'REDUNDANCY', 'RETIREMENT', 'END_OF_CONTRACT'].includes(get(facts, 'exit_ground', '')) &&
  get(facts, 'section_119_ground', false) !== true;
const served = calendar_completed_months(add_months(started, 12 * year), add_days(end, 1));
const owed = dismissed ? Math.max(0, current - (grant * (12 - served)) / 12) : 0;
return ctx.day_rate * (ctx.entry.quantity - current + owed);

