EWF.eligibility:
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const data = get(ctx.subject.employment, 'employee_extension_data', {});
const standing = get(data, 'statutory', {});
const pvd = get(get(standing, 'PVD', {}), 'kind', '');
const ewf = get(get(standing, 'EWF', {}), 'kind', '');
if (ctx.run.salary_coverage.from < ctx.lookup.collection_from) return false;
const base = get(ctx.subtotals, 'ORDINARY_WAGES', ctx.base_pay);
if (base === 0) return false;
const exempt = get(entity, 'ewf_exempt', null);
if (exempt === null || pvd === '' || ewf === '')
  throw 'Record the employer EWF exemption decision and each employee PVD/EWF standing.';
if (exempt === true) return false;
if (ewf === 'VOLUNTARY') return true;
if (ewf !== 'MEMBER') return false;
return pvd !== 'MEMBER';
